package org.eclipse.rdf4j.sail.lmdb;

import static org.junit.jupiter.api.Assertions.assertAll;
import static org.junit.jupiter.api.Assertions.assertArrayEquals;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.nio.file.Files;
import java.nio.file.Path;
import java.util.Properties;
import java.util.concurrent.TimeUnit;

import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.repository.sail.SailRepository;
import org.eclipse.rdf4j.sail.lmdb.config.FrontierEstimatorMode;
import org.eclipse.rdf4j.sail.lmdb.config.LmdbStoreConfig;
import org.junit.jupiter.api.io.TempDir;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.ValueSource;

class LmdbLegacyPolicyStabilityTest {

	@ParameterizedTest(name = "persisted statistics enabled={0}")
	@ValueSource(booleans = { false, true })
	void authenticLegacyPolicySurvivesReadOnlyOpenWritesAndReopen(boolean statistics, @TempDir Path temporaryDirectory)
			throws Exception {
		LmdbCompatibilityFixtures.extract("canonical-iri-format-2.zip", temporaryDirectory);
		Path directory = temporaryDirectory.resolve("store");
		Properties manifest = CanonicalIriCompatibilityProcess.load(temporaryDirectory.resolve("manifest.properties"));
		byte[] original = Files.readAllBytes(directory.resolve("store.properties"));
		tracePolicyBytes(temporaryDirectory, statistics, "original", original);
		var vf = SimpleValueFactory.getInstance();
		var subject = vf.createIRI("urn:legacy-policy:added");
		var predicate = vf.createIRI("urn:legacy-policy:predicate");
		var object = vf.createLiteral("new legacy statement");

		SailRepository first = open(directory, statistics);
		try {
			CanonicalIriCompatibilityProcess.verify(first, manifest);
			if (statistics) {
				LmdbStore store = (LmdbStore) first.getSail();
				assertNotNull(store.getBackingStore().getSketchBasedJoinEstimator());
				assertTrue(store.forceFlushSketchEstimator(), "a real persisted-statistics owner must be ready");
				assertTrue(store.getBackingStore().awaitFrontierStatisticsReady(20_000L));
			}
		} finally {
			first.shutDown();
		}
		byte[] afterReadOnlyOpen = Files.readAllBytes(directory.resolve("store.properties"));
		tracePolicyBytes(temporaryDirectory, statistics, "after-read-only-open", afterReadOnlyOpen);

		SailRepository writer = open(directory, statistics);
		try {
			try (var connection = writer.getConnection()) {
				connection.add(subject, predicate, object);
				assertTrue(connection.hasStatement(subject, predicate, object, false));
			}
		} finally {
			writer.shutDown();
		}
		byte[] afterWrite = Files.readAllBytes(directory.resolve("store.properties"));
		tracePolicyBytes(temporaryDirectory, statistics, "after-statement-commit", afterWrite);

		SailRepository reopened = open(directory, statistics);
		try {
			CanonicalIriCompatibilityProcess.verify(reopened, manifest);
			try (var connection = reopened.getConnection()) {
				assertTrue(connection.hasStatement(subject, predicate, object, false));
			}
		} finally {
			reopened.shutDown();
		}
		byte[] afterReopen = Files.readAllBytes(directory.resolve("store.properties"));
		tracePolicyBytes(temporaryDirectory, statistics, "after-reopen", afterReopen);
		assertAll("the authenticated format-2 policy is not an estimator or no-op migration receipt",
				() -> assertArrayEquals(original, afterReadOnlyOpen, "read-only open"),
				() -> assertArrayEquals(original, afterWrite, "statement commit"),
				() -> assertArrayEquals(original, afterReopen, "subsequent reopen"));
	}

	private static void tracePolicyBytes(Path temporaryDirectory, boolean statistics, String stage, byte[] bytes)
			throws Exception {
		String traceDirectory = System.getProperty("rdf4j.lmdb.policyByteTraceDirectory");
		if (traceDirectory != null) {
			Path destination = Path.of(traceDirectory).resolve("statistics-" + statistics);
			Files.createDirectories(destination);
			Files.write(destination.resolve(stage + ".properties"), bytes);
			Files.writeString(destination.resolve(stage + ".source.txt"), temporaryDirectory.toString() + "\n");
		}
	}

	private static SailRepository open(Path directory, boolean statistics) throws Exception {
		LmdbStoreConfig config = new LmdbStoreConfig("spoc,posc").setTripleTermIndexes("spoc,cspo")
				.setInlineLiterals(false).setAutoGrow(true).setValueDBSize(16L * 1024 * 1024)
				.setTripleDBSize(16L * 1024 * 1024).setSketchEstimatorEnabled(statistics)
				.setFrontierEstimatorMode(statistics ? FrontierEstimatorMode.AUTHORITATIVE : FrontierEstimatorMode.OFF);
		config.setExperimentalQueryOptimizations(statistics);
		LmdbStore store = new LmdbStore(directory.toFile(), config);
		SailRepository repository = new SailRepository(store);
		repository.init();
		try {
			LmdbTestUtil.awaitPostReadyInitialization(store, 20, TimeUnit.SECONDS);
			return repository;
		} catch (Throwable failure) {
			try { repository.shutDown(); } catch (Throwable cleanup) { if (cleanup != failure) { failure.addSuppressed(cleanup); } }
			throw failure;
		}
	}
}
